<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Csrf;use App\Core\Database;use App\Services\SchemaUpdater;$pdo=Database::connection();$eventId=(int)($_GET['event']??$_POST['event_id']??0);$s=$pdo->prepare("SELECT * FROM bdc_events WHERE id=:id AND status='published' AND (registration_opens_at IS NULL OR registration_opens_at<=NOW()) AND (registration_closes_at IS NULL OR registration_closes_at>=NOW())");$s->execute(['id'=>$eventId]);$event=$s->fetch();if(!$event){http_response_code(404);exit('Registration is not available for this event.');}$s=$pdo->prepare("SELECT * FROM bdc_event_ticket_types WHERE event_id=:id AND status='active' AND (sales_start_at IS NULL OR sales_start_at<=NOW()) AND (sales_end_at IS NULL OR sales_end_at>=NOW()) AND (capacity IS NULL OR sold_count<capacity) ORDER BY sort_order,id");$s->execute(['id'=>$eventId]);$tickets=$s->fetchAll();$error='';$success='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');if(!isset($_POST['terms']))throw new RuntimeException('You must accept the terms and conditions.');$ticketId=(int)$_POST['ticket_type_id'];$name=trim((string)$_POST['full_name']);$email=strtolower(trim((string)$_POST['email']));$phone=trim((string)$_POST['phone']);if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$phone==='')throw new RuntimeException('Name, valid email and contact number are required.');$method=(string)$_POST['payment_method'];if(!in_array($method,['paynow','bank_transfer','cash'],true))throw new RuntimeException('Invalid payment method.');$paymentStatus=$method==='cash'?'cash_at_venue':'pending';$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM bdc_event_ticket_types WHERE id=:id AND event_id=:event AND status='active' AND (sales_start_at IS NULL OR sales_start_at<=NOW()) AND (sales_end_at IS NULL OR sales_end_at>=NOW()) FOR UPDATE");$s->execute(['id'=>$ticketId,'event'=>$eventId]);$ticket=$s->fetch();if(!$ticket)throw new RuntimeException('This ticket is not currently available.');$count=$pdo->prepare("SELECT COUNT(*) FROM bdc_event_registrations WHERE ticket_type_id=:ticket AND registration_status NOT IN ('rejected','cancelled')");$count->execute(['ticket'=>$ticketId]);$reserved=(int)$count->fetchColumn();if($ticket['capacity']!==null&&$reserved>=(int)$ticket['capacity'])throw new RuntimeException('This ticket is sold out.');$duplicate=$pdo->prepare("SELECT 1 FROM bdc_event_registrations WHERE event_id=:event AND email=:email AND registration_status NOT IN ('rejected','cancelled') LIMIT 1 FOR UPDATE");$duplicate->execute(['event'=>$eventId,'email'=>$email]);if($duplicate->fetchColumn())throw new RuntimeException('A registration for this email already exists for this event.');$reg='REG-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$pdo->prepare('INSERT INTO bdc_event_registrations(event_id,ticket_type_id,registration_number,full_name,email,phone,instagram,country,dance_role,dance_category,includes_jack_jill,registration_status,payment_status,terms_accepted_at,submitted_ip) VALUES(:event,:ticket,:reg,:name,:email,:phone,:instagram,:country,:role,:category,:jj,\'pending_verification\',:payment,NOW(),:ip)')->execute(['event'=>$eventId,'ticket'=>$ticketId,'reg'=>$reg,'name'=>$name,'email'=>$email,'phone'=>$phone,'instagram'=>trim((string)$_POST['instagram']),'country'=>trim((string)$_POST['country']),'role'=>$_POST['dance_role'],'category'=>trim((string)$_POST['dance_category']),'jj'=>(int)$ticket['includes_jack_jill'],'payment'=>$paymentStatus,'ip'=>$_SERVER['REMOTE_ADDR']??null]);$rid=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE bdc_event_ticket_types SET sold_count=:count WHERE id=:id')->execute(['count'=>$reserved+1,'id'=>$ticketId]);$pdo->prepare('INSERT INTO bdc_registration_payments(registration_id,payment_method,expected_amount,paid_amount,currency,payment_reference,verification_status) VALUES(:rid,:method,:expected,:paid,:currency,:ref,:status)')->execute(['rid'=>$rid,'method'=>$method,'expected'=>$ticket['price'],'paid'=>$_POST['paid_amount']!==''?(float)$_POST['paid_amount']:null,'currency'=>$ticket['currency'],'ref'=>trim((string)$_POST['payment_reference']),'status'=>$paymentStatus]);
 if(isset($_FILES['receipt'])&&($_FILES['receipt']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK){$f=$_FILES['receipt'];if((int)$f['size']>10*1024*1024)throw new RuntimeException('Receipt must be 10 MB or smaller.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))throw new RuntimeException('Receipt must be JPG, PNG or PDF.');$stored=date('YmdHis').'-'.bin2hex(random_bytes(8)).'.'.$allowed[$mime];$dir=dirname(__DIR__).'/storage/registration-receipts';if(!is_dir($dir))mkdir($dir,0750,true);if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$stored))throw new RuntimeException('Could not store receipt.');$pdo->prepare('INSERT INTO bdc_registration_uploads(registration_id,original_filename,stored_filename,storage_path,mime_type,file_size) VALUES(:rid,:original,:stored,:path,:mime,:size)')->execute(['rid'=>$rid,'original'=>$f['name'],'stored'=>$stored,'path'=>'storage/registration-receipts/'.$stored,'mime'=>$mime,'size'=>$f['size']]);}elseif($method!=='cash')throw new RuntimeException('Please upload your payment receipt.');$pdo->commit();$success='Registration submitted. Your registration number is '.$reg.'. Payment verification is pending.';}
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($event['name'])?> Registration</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light">
<a href="https://bachatadancecouncil.com/" class="bdc-global-home-link" style="position:fixed;top:12px;right:12px;z-index:1090;display:inline-flex;align-items:center;gap:.35rem;padding:.4rem .7rem;border:1px solid #d7a51f;border-radius:.4rem;background:#d9a928;color:#172033;font:600 14px/1.2 Arial,sans-serif;text-decoration:none;box-shadow:0 2px 8px rgba(0,0,0,.18)">🏠 BDC Home</a>
<main class="container py-5" style="max-width:850px"><div class="card border-0 shadow"><div class="card-body p-4 p-md-5"><h1><?=e($event['name'])?></h1><div class="text-muted mb-3"><?=e((string)$event['event_date'])?> · <?=e((string)($event['venue']?:$event['location']))?></div><div class="mb-4" style="white-space:pre-wrap"><?=e($event['description'])?></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php else:?><form method="post" enctype="multipart/form-data" class="row g-3"><?=Csrf::field()?><input type="hidden" name="event_id" value="<?=$eventId?>"><div class="col-md-6"><label class="form-label">Full name *</label><input class="form-control" name="full_name" required></div><div class="col-md-3"><label class="form-label">Role *</label><select class="form-select" name="dance_role" required><option value="leader">Lead</option><option value="follower">Follow</option></select></div><div class="col-md-3"><label class="form-label">Category *</label><input class="form-control" name="dance_category" placeholder="Bachata" required></div><div class="col-md-6"><label class="form-label">Contact number *</label><input class="form-control" name="phone" required></div><div class="col-md-6"><label class="form-label">Email *</label><input type="email" class="form-control" name="email" required></div><div class="col-md-6"><label class="form-label">Instagram</label><input class="form-control" name="instagram"></div><div class="col-md-6"><label class="form-label">Country</label><input class="form-control" name="country"></div><div class="col-12"><label class="form-label">Ticket/pass *</label><select class="form-select" name="ticket_type_id" required><?php foreach($tickets as $t):?><option value="<?=$t['id']?>"><?=e($t['name'])?> — <?=e($t['currency'])?> <?=number_format((float)$t['price'],2)?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Payment method *</label><select class="form-select" name="payment_method"><option value="paynow">PayNow</option><option value="bank_transfer">Bank Transfer</option><option value="cash">Cash</option></select></div><div class="col-md-4"><label class="form-label">Amount paid</label><input type="number" step="0.01" class="form-control" name="paid_amount"></div><div class="col-md-4"><label class="form-label">Reference</label><input class="form-control" name="payment_reference"></div><div class="col-12"><div class="alert alert-secondary" style="white-space:pre-wrap"><?=e($event['payment_instructions'])?></div><label class="form-label">Upload receipt</label><input type="file" class="form-control" name="receipt" accept="image/jpeg,image/png,application/pdf"></div><div class="col-12"><div class="border rounded p-3 small" style="white-space:pre-wrap"><?=e($event['terms_conditions'])?></div><label class="mt-2"><input type="checkbox" name="terms" value="1" required> Yes, I accept the terms and conditions.</label></div><div class="col-12"><button class="btn btn-dark btn-lg">Submit Registration</button></div></form><?php endif;?></div></div></main></body></html>
